export function bindEvents(t){document.addEventListener("pointermove",e=>{const n=t.cardFrom(e.target);if(!n)return;const r=n.getBoundingClientRect();if(!r.width||!r.height)return;const o=(e.clientX-r.left)/r.width*100,i=(e.clientY-r.top)/r.height*100;n.style.setProperty("--mx",`${o.toFixed(1)}%`),n.style.setProperty("--my",`${i.toFixed(1)}%`)},{passive:!0}),document.addEventListener("pointerout",e=>{const n=t.cardFrom(e.target);!n||e.relatedTarget instanceof Node&&n.contains(e.relatedTarget)||(n.style.setProperty("--mx","50%"),n.style.setProperty("--my","50%"))},{passive:!0}),t.applyAccents(),window.addEventListener("zqwy:pagechange",()=>t.applyAccents())}